#[test]
fn x25519_matches_python() {
    for (secret, public, peer_public, shared) in DH {
        let s = a32(secret);
        assert_eq!(x25519::public_key(&s), a32(public));
        assert_eq!(
            x25519::shared_secret(&s, &a32(peer_public)).unwrap(),
            a32(shared)
        );
    }
}

#[test]
fn ed25519_matches_python() {
    for (seed, public, msg, sig) in SIG {
        let (seed, msg) = (a32(seed), hex(msg));
        let sig: [u8; 64] = hex(sig).try_into().unwrap();
        assert_eq!(ed25519::public_key(&seed), a32(public));
        assert_eq!(ed25519::sign(&seed, &msg), sig);
        assert!(ed25519::verify(&a32(public), &msg, &sig).is_ok());
        let mut bad = sig;
        bad[msg.len() % 64] ^= 1;
        assert!(ed25519::verify(&a32(public), &msg, &bad).is_err());
    }
}
